static unsigned int shark_catalog_count_kind(unsigned int kind)
{
	unsigned int count = 0;
	unsigned int i;

	for (i = 0; i < SHARK_SOC_STATIC_CATALOG_COUNT; i++)
		if (shark_soc_static_catalog[i].kind == kind)
			count++;

	return count;
}

static bool shark_catalog_rate_present(
	const struct shark_soc_catalog_table *levels, unsigned int rate)
{
	unsigned int i;

	for (i = 0; i < levels->cols; i++)
		if (shark_normalize_rate(levels->name,
			(unsigned int)levels->data[i]) == rate)
			return true;

	return false;
}

static int shark_validate_pll_catalog(
	const struct shark_soc_catalog_table *table)
{
	u64 previous = 0;
	bool saw_zero = false;
	unsigned int i;

	if (table->cols != 5U)
		return -EINVAL;

	for (i = 0; i < table->rows; i++) {
		const u64 *data = &table->data[i * table->cols];

		if (!data[0]) {
			saw_zero = true;
			continue;
		}
		if (saw_zero || (previous && data[0] >= previous) ||
		    !data[1] || !data[2])
			return -ERANGE;
		previous = data[0];
	}

	return previous ? 0 : -ENODATA;
}

static int shark_validate_dvfs_catalog(
	const struct shark_soc_catalog_table *levels)
{
	const struct shark_soc_catalog_table *enabled;
	const struct shark_soc_catalog_table *params;
	const struct shark_soc_catalog_table *freqs;
	const struct shark_soc_catalog_table *sfr;
	unsigned int previous = 0;
	unsigned int i, version;

	if (levels->rows != 1U || !levels->cols ||
	    levels->cols > SHARK_SOC_MAX_DOMAIN_OPPS)
		return -EINVAL;
	if ((levels->aux0 != ~0U && levels->aux0 >= levels->cols) ||
	    (levels->aux1 != ~0U && levels->aux1 >= levels->cols))
		return -ERANGE;

	enabled = shark_soc_catalog_find("DVFS", levels->name, "enabled",
		SHARK_SOC_CATALOG_DVFS_ENABLED);
	sfr = shark_soc_catalog_find("DVFS", levels->name, "sfr",
		SHARK_SOC_CATALOG_DVFS_SFR);
	params = shark_soc_catalog_find("DVFS", levels->name, "params",
		SHARK_SOC_CATALOG_DVFS_PARAMS);
	freqs = shark_soc_catalog_find("ASV", levels->name, "frequencies",
		SHARK_SOC_CATALOG_ASV_FREQS);
	if (!enabled || !sfr || !params || !freqs ||
	    enabled->rows != 1U || enabled->cols != levels->cols ||
	    sfr->rows != 1U || !sfr->cols ||
	    params->rows != levels->cols || params->cols != sfr->cols ||
	    freqs->rows != 1U || freqs->cols != levels->cols ||
	    !freqs->aux0 || !freqs->aux1)
		return -EINVAL;

	for (i = 0; i < levels->cols; i++) {
		u64 asv_rate = freqs->data[i] * 1000ULL;
		unsigned int rate;

		if (levels->data[i] > ~0U || asv_rate > ~0U ||
		    enabled->data[i] > 1U)
			return -ERANGE;
		rate = shark_normalize_rate(levels->name,
			(unsigned int)levels->data[i]);
		if (!rate || (previous && rate >= previous) ||
		    rate != shark_normalize_rate(levels->name,
			(unsigned int)asv_rate))
			return -ERANGE;
		previous = rate;
	}

	for (version = 1; version <= freqs->aux1; version++) {
		const struct shark_soc_catalog_table *table;
		char subname[24];
		unsigned int cell;

		snprintf(subname, sizeof(subname), "table_v%u", version);
		table = shark_soc_catalog_find("ASV", levels->name, subname,
			SHARK_SOC_CATALOG_ASV_TABLE);
		if (!table || table->rows != levels->cols ||
		    table->cols != freqs->aux0 ||
		    (table->aux0 != ~0U && table->aux0 >= levels->cols) ||
		    (table->aux1 != ~0U && table->aux1 >= levels->cols))
			return -EINVAL;
		for (cell = 0; cell < table->rows * table->cols; cell++) {
			u64 voltage = table->data[cell];

			if (voltage && (voltage > ~0U ||
			    !shark_voltage_valid((unsigned int)voltage)))
				return -ERANGE;
		}
	}

	return 0;
}

static int shark_validate_minlock_catalog(
	const struct shark_soc_catalog_table *table)
{
	const struct shark_soc_catalog_table *levels;
	unsigned int i;

	if (table->cols != 2U)
		return -EINVAL;
	levels = shark_soc_catalog_find("DVFS", table->name, "levels",
		SHARK_SOC_CATALOG_DVFS_LEVELS);
	if (!levels)
		return -ENOENT;

	for (i = 0; i < table->rows; i++) {
		unsigned int main;

		if (table->data[i * 2U] > ~0U ||
		    table->data[i * 2U + 1U] > ~0U)
			return -ERANGE;
		main = shark_normalize_rate(table->name,
			(unsigned int)table->data[i * 2U]);
		if (!main || !table->data[i * 2U + 1U] ||
		    !shark_catalog_rate_present(levels, main))
			return -ERANGE;
	}

	return 0;
}

static int shark_validate_policy_catalog(void)
{
	const struct shark_soc_catalog_table *bigturbo;
	const struct shark_soc_catalog_table *cpucl0;
	const struct shark_soc_catalog_table *cpucl1;
	const struct shark_soc_catalog_table *cam;
	const struct shark_soc_catalog_table *g3d;
	const struct shark_soc_catalog_table *int_domain;
	const struct shark_soc_catalog_table *intcam;
	const struct shark_soc_catalog_table *mif;
	unsigned int i, j;

	cpucl0 = shark_soc_catalog_find("DVFS", "dvfs_cpucl0", "levels",
		SHARK_SOC_CATALOG_DVFS_LEVELS);
	cpucl1 = shark_soc_catalog_find("DVFS", "dvfs_cpucl1", "levels",
		SHARK_SOC_CATALOG_DVFS_LEVELS);
	cam = shark_soc_catalog_find("DVFS", "dvfs_cam", "levels",
		SHARK_SOC_CATALOG_DVFS_LEVELS);
	g3d = shark_soc_catalog_find("DVFS", "dvfs_g3d", "levels",
		SHARK_SOC_CATALOG_DVFS_LEVELS);
	int_domain = shark_soc_catalog_find("DVFS", "dvfs_int", "levels",
		SHARK_SOC_CATALOG_DVFS_LEVELS);
	intcam = shark_soc_catalog_find("DVFS", "dvfs_intcam", "levels",
		SHARK_SOC_CATALOG_DVFS_LEVELS);
	mif = shark_soc_catalog_find("DVFS", "dvfs_mif", "levels",
		SHARK_SOC_CATALOG_DVFS_LEVELS);
	bigturbo = shark_soc_catalog_find("GEN", "BIGTURBO", "parameters",
		SHARK_SOC_CATALOG_GEN_TABLE);
	if (!cpucl0 || !cpucl1 || !cam || !g3d || !int_domain || !intcam ||
	    !mif || !bigturbo ||
	    bigturbo->rows != 8U || bigturbo->cols != 4U ||
	    ARRAY_SIZE(shark_devfreq_policies) != 5U ||
	    ARRAY_SIZE(shark_cpu_policies) != 2U ||
	    ARRAY_SIZE(shark_gpu_dvfs_table) != g3d->cols)
		return -EINVAL;

	for (i = 0; i < ARRAY_SIZE(shark_devfreq_policies); i++) {
		const struct shark_soc_devfreq_policy *policy;
		const struct shark_soc_catalog_table *levels;
		const unsigned int *frequency;

		levels = shark_soc_catalog_find("DVFS",
			shark_devfreq_policies[i].name, "levels",
			SHARK_SOC_CATALOG_DVFS_LEVELS);
		if (!levels)
			return -ENOENT;
		policy = &shark_devfreq_policies[i].policy;
		frequency = &policy->initial_freq;
		for (j = 0; j < sizeof(*policy) / sizeof(*frequency); j++)
			if (!shark_catalog_rate_present(levels, frequency[j]))
				return -ERANGE;
		if (policy->max_freq < policy->min_freq ||
		    policy->max_freq != levels->data[0] ||
		    policy->min_freq != levels->data[levels->cols - 1U])
			return -ERANGE;
	}
	for (i = 0; i < bigturbo->rows * bigturbo->cols; i++)
		if (bigturbo->data[i] > ~0U ||
		    !shark_catalog_rate_present(cpucl0,
			(unsigned int)bigturbo->data[i]))
			return -ERANGE;

	for (i = 0; i < ARRAY_SIZE(shark_cpu_policies); i++) {
		const struct shark_soc_cpu_policy *policy;
		const struct shark_soc_catalog_table *levels;
		const unsigned int *frequency;

		levels = shark_soc_catalog_find("DVFS",
			shark_cpu_policies[i].name, "levels",
			SHARK_SOC_CATALOG_DVFS_LEVELS);
		if (!levels)
			return -ENOENT;
		policy = &shark_cpu_policies[i].policy;
		frequency = &policy->boot_qos;
		for (j = 0; j < sizeof(*policy) / sizeof(*frequency); j++)
			if (frequency[j] &&
			    !shark_catalog_rate_present(levels, frequency[j]))
				return -ERANGE;
	}

	for (i = 0; i < ARRAY_SIZE(shark_gpu_dvfs_table); i++) {
		const struct shark_soc_gpu_dvfs_entry *entry;
		unsigned int rate;

		entry = &shark_gpu_dvfs_table[i];
		rate = shark_normalize_rate(g3d->name,
			(unsigned int)g3d->data[i]);
		if (entry->clock != rate || entry->min_threshold > 100U ||
		    entry->max_threshold > 100U ||
		    entry->min_threshold >= entry->max_threshold ||
		    !entry->down_staycount ||
		    !shark_catalog_rate_present(mif, entry->mif_freq) ||
		    (entry->cpu_little_min_freq &&
		     !shark_catalog_rate_present(cpucl1,
			entry->cpu_little_min_freq)) ||
		    (entry->cpu_big_max_freq &&
		     !shark_catalog_rate_present(cpucl0,
			entry->cpu_big_max_freq)))
			return -ERANGE;
	}

	for (i = 0; i < ARRAY_SIZE(shark_gpu_thermal_rates); i++)
		if (!shark_catalog_rate_present(g3d,
			shark_gpu_thermal_rates[i]))
			return -ERANGE;

	for (i = 0; i < ARRAY_SIZE(shark_dm_policies); i++) {
		const struct shark_soc_catalog_table *levels;
		const struct shark_frequency_pair *previous = NULL;

		levels = shark_soc_catalog_find("DVFS", shark_dm_policies[i].name,
			"levels", SHARK_SOC_CATALOG_DVFS_LEVELS);
		if (!levels || !shark_dm_policies[i].count)
			return -EINVAL;
		for (j = 0; j < shark_dm_policies[i].count; j++) {
			const struct shark_frequency_pair *pair;

			pair = &shark_dm_policies[i].table[j];
			if ((previous && pair->master >= previous->master) ||
			    !shark_catalog_rate_present(levels, pair->master) ||
			    !shark_catalog_rate_present(mif, pair->dependent))
				return -ERANGE;
			previous = pair;
		}
	}

	for (i = 0; i < ARRAY_SIZE(shark_ufc_min_table); i++)
		if (!shark_catalog_rate_present(cpucl0,
			shark_ufc_min_table[i].master) ||
		    !shark_catalog_rate_present(cpucl1,
			shark_ufc_min_table[i].dependent))
			return -ERANGE;
	for (i = 0; i < ARRAY_SIZE(shark_ufc_max_table); i++) {
		if ((i && shark_ufc_max_table[i].master >=
		     shark_ufc_max_table[i - 1U].master) ||
		    !shark_catalog_rate_present(cpucl0,
			shark_ufc_max_table[i].master) ||
		    !shark_catalog_rate_present(cpucl1,
			shark_ufc_max_table[i].dependent))
			return -ERANGE;
	}

	for (i = 0; i < ARRAY_SIZE(shark_hmp_softlanding_rates); i++)
		if (!shark_catalog_rate_present(cpucl1,
			shark_hmp_softlanding_rates[i]))
			return -ERANGE;
	if (!(ARRAY_SIZE(shark_schedtune_cpucl1_table) & 1U) ||
	    !(ARRAY_SIZE(shark_schedtune_cpucl0_table) & 1U))
		return -EINVAL;
	for (i = 0; i < ARRAY_SIZE(shark_schedtune_cpucl1_table); i++) {
		if (!(i & 1U)) {
			if (shark_schedtune_cpucl1_table[i] > 100U)
				return -ERANGE;
		} else if (!shark_catalog_rate_present(cpucl1,
			shark_schedtune_cpucl1_table[i])) {
			return -ERANGE;
		}
	}
	for (i = 0; i < ARRAY_SIZE(shark_schedtune_cpucl0_table); i++) {
		if (!(i & 1U)) {
			if (shark_schedtune_cpucl0_table[i] > 100U)
				return -ERANGE;
		} else if (!shark_catalog_rate_present(cpucl0,
			shark_schedtune_cpucl0_table[i])) {
			return -ERANGE;
		}
	}
	if (!shark_catalog_rate_present(cpucl0,
		shark_input_boost_policy.cpu_freq) ||
	    !shark_catalog_rate_present(cpucl1,
		shark_input_boost_policy.kfc_freq))
		return -ERANGE;
	for (i = 0; i < ARRAY_SIZE(shark_mfc_qos_frequencies); i++) {
		const struct shark_soc_mfc_qos_frequency *entry;

		entry = &shark_mfc_qos_frequencies[i];
		if (!entry->mfc_freq ||
		    !shark_catalog_rate_present(int_domain, entry->int_freq) ||
		    !shark_catalog_rate_present(mif, entry->mif_freq) ||
		    entry->cpu_freq || entry->kfc_freq)
			return -ERANGE;
	}
	for (i = 0; i < ARRAY_SIZE(shark_camera_qos_base); i++) {
		const struct shark_soc_camera_qos_policy *entry;

		entry = &shark_camera_qos_base[i];
		if (!entry->int_cam_freq) {
			if (entry->int_freq || entry->cam_freq || entry->mif_freq ||
			    entry->i2c_level || entry->hpg)
				return -ERANGE;
			continue;
		}
		if (!shark_catalog_rate_present(intcam, entry->int_cam_freq) ||
		    !shark_catalog_rate_present(int_domain, entry->int_freq) ||
		    !shark_catalog_rate_present(cam, entry->cam_freq) ||
		    !shark_catalog_rate_present(mif, entry->mif_freq) ||
		    entry->i2c_level || !entry->hpg || entry->hpg > 8U)
			return -ERANGE;
	}
	for (i = 0; i < ARRAY_SIZE(shark_camera_qos_table1); i++) {
		const struct shark_camera_qos_override *override;
		const struct shark_soc_camera_qos_policy *entry;

		override = &shark_camera_qos_table1[i];
		entry = &override->policy;
		if (override->scenario >= SHARK_CAMERA_QOS_SCENARIO_COUNT)
			return -ERANGE;
		for (j = i + 1U; j < ARRAY_SIZE(shark_camera_qos_table1); j++)
			if (override->scenario ==
			    shark_camera_qos_table1[j].scenario)
				return -EINVAL;
		if (!entry->int_cam_freq) {
			if (entry->int_freq || entry->cam_freq || entry->mif_freq ||
			    entry->i2c_level || entry->hpg)
				return -ERANGE;
			continue;
		}
		if (!shark_catalog_rate_present(intcam, entry->int_cam_freq) ||
		    !shark_catalog_rate_present(int_domain, entry->int_freq) ||
		    !shark_catalog_rate_present(cam, entry->cam_freq) ||
		    !shark_catalog_rate_present(mif, entry->mif_freq) ||
		    entry->i2c_level || !entry->hpg || entry->hpg > 8U)
			return -ERANGE;
	}
	for (i = 0; i < ARRAY_SIZE(shark_g2d_qos_table); i++) {
		const struct shark_soc_g2d_qos_frequency *entry;

		entry = &shark_g2d_qos_table[i];
		if ((entry->cpucl0_freq &&
		     !shark_catalog_rate_present(cpucl0, entry->cpucl0_freq)) ||
		    (entry->cpucl1_freq &&
		     !shark_catalog_rate_present(cpucl1, entry->cpucl1_freq)) ||
		    (entry->mif_freq &&
		     !shark_catalog_rate_present(mif, entry->mif_freq)))
			return -ERANGE;
	}
	for (i = 0; i < ARRAY_SIZE(shark_client_qos_policies); i++) {
		const struct shark_client_qos_policy *policy;
		const struct shark_soc_catalog_table *levels;

		policy = &shark_client_qos_policies[i];
		levels = shark_soc_catalog_find("DVFS", policy->domain, "levels",
			SHARK_SOC_CATALOG_DVFS_LEVELS);
		if (!levels || !policy->count)
			return -EINVAL;
		for (j = 0; j < policy->count; j++)
			if (policy->rates[j] &&
			    !shark_catalog_rate_present(levels, policy->rates[j]))
				return -ERANGE;
	}
	for (i = 0; i < ARRAY_SIZE(shark_nad_policies); i++) {
		const struct shark_client_qos_policy *policy;
		const struct shark_soc_catalog_table *levels;

		policy = &shark_nad_policies[i];
		levels = shark_soc_catalog_find("DVFS", policy->domain, "levels",
			SHARK_SOC_CATALOG_DVFS_LEVELS);
		if (!levels || !policy->count)
			return -EINVAL;
		for (j = 0; j < policy->count; j++)
			if (!shark_catalog_rate_present(levels, policy->rates[j]))
				return -ERANGE;
	}
	for (i = 0; i < ARRAY_SIZE(shark_argos_policies); i++) {
		const struct shark_argos_policy *policy;

		policy = &shark_argos_policies[i];
		if (!policy->count)
			return -EINVAL;
		for (j = i + 1U; j < ARRAY_SIZE(shark_argos_policies); j++)
			if (!strcmp(policy->label, shark_argos_policies[j].label))
				return -EINVAL;
		for (j = 0; j < policy->count; j++) {
			const struct shark_soc_argos_frequency *entry;

			entry = &policy->table[j];
			if ((entry->cpu_min_freq &&
			     !shark_catalog_rate_present(cpucl0,
				entry->cpu_min_freq)) ||
			    (entry->cpu_max_freq &&
			     !shark_catalog_rate_present(cpucl0,
				entry->cpu_max_freq)) ||
			    (entry->kfc_min_freq &&
			     !shark_catalog_rate_present(cpucl1,
				entry->kfc_min_freq)) ||
			    (entry->kfc_max_freq &&
			     !shark_catalog_rate_present(cpucl1,
				entry->kfc_max_freq)) ||
			    (entry->mif_freq &&
			     !shark_catalog_rate_present(mif, entry->mif_freq)) ||
			    (entry->int_freq &&
			     !shark_catalog_rate_present(int_domain,
				entry->int_freq)))
				return -ERANGE;
		}
	}

	return 0;
}

static int shark_validate_static_catalog(void)
{
	int ret;
	unsigned int i, j;

	for (i = 0; i < ARRAY_SIZE(shark_catalog_expectations); i++)
		if (shark_catalog_count_kind(
			shark_catalog_expectations[i].kind) !=
		    shark_catalog_expectations[i].count)
			return -EINVAL;

	for (i = 0; i < SHARK_SOC_STATIC_CATALOG_COUNT; i++) {
		const struct shark_soc_catalog_table *table;

		table = &shark_soc_static_catalog[i];
		if (!table->block || !table->block[0] || !table->name ||
		    !table->name[0] || !table->subname ||
		    !table->subname[0] || !table->data ||
		    !table->rows || !table->cols ||
		    table->kind <= SHARK_SOC_CATALOG_ANY ||
		    table->kind > SHARK_SOC_CATALOG_THERMAL_RANGES)
			return -EINVAL;

		for (j = i + 1; j < SHARK_SOC_STATIC_CATALOG_COUNT; j++) {
			const struct shark_soc_catalog_table *peer;

			peer = &shark_soc_static_catalog[j];
			if (table->kind == peer->kind &&
			    !strcmp(table->block, peer->block) &&
			    !strcmp(table->name, peer->name) &&
			    !strcmp(table->subname, peer->subname))
				return -EEXIST;
		}

		if (table->kind == SHARK_SOC_CATALOG_PLL_RATES &&
		    shark_validate_pll_catalog(table))
			return -ERANGE;
		if (table->kind == SHARK_SOC_CATALOG_DVFS_LEVELS &&
		    shark_validate_dvfs_catalog(table))
			return -ERANGE;
		if (table->kind == SHARK_SOC_CATALOG_MINLOCK_TABLE &&
		    shark_validate_minlock_catalog(table))
			return -ERANGE;
	}

	ret = shark_validate_policy_catalog();
	if (ret)
		return ret;

	return 0;
}

static void shark_registry_init(void)
{
	int ret;
	unsigned int i;

	mutex_lock(&shark_init_lock);
	if (shark_registry_ready)
		goto out;

	ret = shark_validate_static_catalog();
	if (ret)
		goto invalid;

	for (i = 0; i < SHARK_SOC_STATIC_CATALOG_COUNT; i++) {
		const struct shark_soc_catalog_table *table;
		struct shark_domain *domain;
		unsigned int level;

		table = &shark_soc_static_catalog[i];
		if (table->kind != SHARK_SOC_CATALOG_DVFS_LEVELS)
			continue;
		if (shark_domain_count >= ARRAY_SIZE(shark_domains) ||
		    table->cols > SHARK_SOC_MAX_DOMAIN_OPPS) {
			ret = -ENOSPC;
			goto invalid;
		}

		domain = &shark_domains[shark_domain_count++];
		domain->name = table->name;
		domain->id = SHARK_SOC_DOMAIN_ID_ANY;
		domain->count = table->cols;
		domain->boot_level = table->aux0;
		domain->resume_level = table->aux1;
		for (level = 0; level < domain->count; level++)
			domain->rates[level] = shark_normalize_rate(
				domain->name, (unsigned int)table->data[level]);
		domain->max_freq = domain->rates[0];
		domain->min_freq = domain->rates[domain->count - 1];
		if (domain->boot_level < domain->count)
			domain->boot_freq = domain->rates[domain->boot_level];
		if (domain->resume_level < domain->count)
			domain->resume_freq =
				domain->rates[domain->resume_level];
	}
	if (shark_domain_count != ARRAY_SIZE(shark_domains)) {
		ret = -EINVAL;
		goto invalid;
	}

	shark_catalog_result = 0;
	shark_catalog_valid = true;
	shark_registry_ready = true;
	pr_info("Shark DVFS: validated %u catalog tables and %u domains\n",
		(unsigned int)SHARK_SOC_STATIC_CATALOG_COUNT,
		shark_domain_count);
	goto out;

invalid:
	memset(shark_domains, 0, sizeof(shark_domains));
	shark_domain_count = 0;
	shark_catalog_result = ret;
	shark_catalog_valid = false;
	shark_registry_ready = true;
	pr_err("Shark DVFS: static catalog validation failed (%d)\n", ret);
out:
	mutex_unlock(&shark_init_lock);
}

static struct shark_domain *shark_find_domain(const char *name,
					       unsigned int domain_id)
{
	const char *canonical_name = shark_canonical_domain_name(name);
	struct shark_domain *id_match = NULL;
	unsigned int i;

	shark_registry_init();
	for (i = 0; i < shark_domain_count; i++) {
		struct shark_domain *domain = &shark_domains[i];

		if (canonical_name && !strcmp(canonical_name, domain->name)) {
			if (domain_id != SHARK_SOC_DOMAIN_ID_ANY &&
			    domain->id != SHARK_SOC_DOMAIN_ID_ANY &&
			    domain->id != domain_id)
				return NULL;
			return domain;
		}
		if (domain_id != SHARK_SOC_DOMAIN_ID_ANY &&
		    domain->id == domain_id)
			id_match = domain;
	}

	return canonical_name ? NULL : id_match;
}

static unsigned int shark_domain_rate(const char *name, unsigned int level,
				      unsigned int fallback)
{
	struct shark_domain *domain;

	domain = shark_find_domain(name, SHARK_SOC_DOMAIN_ID_ANY);
	if (!domain || level >= domain->count)
		return shark_normalize_rate(name, fallback);

	return domain->rates[level];
}

static bool shark_domain_has_rate(const struct shark_domain *domain,
				  unsigned int rate)
{
	unsigned int i;

	if (!rate || rate == ~0U)
		return false;

	for (i = 0; i < domain->count; i++)
		if (domain->rates[i] == rate)
			return true;

	return false;
}

int shark_soc_get_domain_table(const char *name, unsigned int domain_id,
			       unsigned int *rates_khz,
			       unsigned int *volts_uv,
			       unsigned int capacity,
			       unsigned int *count)
{
	struct shark_domain *domain;
	unsigned int i;

	if (!count)
		return -EINVAL;
	if (!shark_soc_is_enabled())
		return -ENODEV;

	mutex_lock(&shark_lock);
	domain = shark_find_domain(name, domain_id);
	if (!domain) {
		mutex_unlock(&shark_lock);
		return -ENOENT;
	}
	*count = domain->count;
	if (capacity < domain->count) {
		mutex_unlock(&shark_lock);
		return -ENOSPC;
	}
	for (i = 0; i < domain->count; i++) {
		if (rates_khz)
			rates_khz[i] = domain->rates[i];
		if (volts_uv)
			volts_uv[i] = domain->volts[i];
	}
	mutex_unlock(&shark_lock);

	return 0;
}
EXPORT_SYMBOL_GPL(shark_soc_get_domain_table);

